function clamp(value, min, max) {
  return Math.min(Math.max(value, min), max);
}

function hasClosest(target, selector) {
  return Boolean(
    target && typeof target.closest === 'function' && target.closest(selector),
  );
}

function containsNode(container, node) {
  return Boolean(
    container &&
    node &&
    typeof container.contains === 'function' &&
    container.contains(node),
  );
}

function createAnimationFrame(ownerWindow) {
  if (typeof ownerWindow?.requestAnimationFrame === 'function') {
    return ownerWindow.requestAnimationFrame.bind(ownerWindow);
  }

  return (callback) => ownerWindow.setTimeout(callback, 0);
}

function ensureElement(name, value) {
  if (!value) {
    throw new Error(`Khmer NiDA keyboard requires ${name}.`);
  }

  return value;
}

