    const width =
      keyboard.clientWidth || state.size.expandedWidth || state.size.baseWidth;
    const height =
      keyboard.clientHeight ||
      state.size.expandedHeight ||
      state.size.baseHeight;
    const contentWidthScale = width / state.size.baseWidth;
    const contentHeightScale = height / state.size.baseHeight;
    const contentScale = clamp(
      Math.min(contentWidthScale, contentHeightScale),
      1,
      2.4,
    );
