import {
  createDictionarySnapshot,
  getDictionaryPrefixSuggestions,
  getDictionaryConfig,
  getSuggestionDictionaryConfigs,
  hasAnyWordBaseCharacter,
  loadDictionary,
  normalizeWord,
} from '../../editor/scripts/spellcheck-common.ts';
import { logEditorTiming } from '../../editor/scripts/helpers.ts';

const khmerDictionarySnapshotPromises = new Map();
const KHMER_SEGMENTATION_SEPARATOR = '\u200B';
const IOS_OR_ANDROID_PLATFORM_RE = /android|ios|iphone|ipad|ipod/iu;
const IOS_OR_ANDROID_USER_AGENT_RE = /android|iphone|ipad|ipod/iu;
const IPADOS_DESKTOP_USER_AGENT_RE = /macintosh/iu;
const KHMER_MOBILE_TRANSCRIPT_ARTIFACT_RE = /\u1780\*\*/gu;
const KHMER_MOBILE_TRANSCRIPT_ARTIFACT_REPLACEMENT = '\u1780\u17D2\u178F';

function getKhmerTimingNow() {
  return typeof globalThis.performance?.now === 'function'
    ? globalThis.performance.now()
    : Date.now();
}

function logKhmerProviderTiming(label, startTime, details = '') {
  const durationMs = getKhmerTimingNow() - startTime;
  logEditorTiming(
    console.info,
    `provider ${label}: ${durationMs.toFixed(1)}ms${details ? ` ${details}` : ''}`,
  );
  return durationMs;
}

function isLikelyIosOrAndroidBrowser(ownerNavigator = globalThis.navigator) {
  if (!ownerNavigator) {
    return false;
  }

  const platform = String(
    ownerNavigator.userAgentData?.platform || ownerNavigator.platform || '',
  );
  if (IOS_OR_ANDROID_PLATFORM_RE.test(platform)) {
    return true;
  }

  const userAgent = String(ownerNavigator.userAgent || '');
  if (IOS_OR_ANDROID_USER_AGENT_RE.test(userAgent)) {
    return true;
  }

  const maxTouchPoints = Number(ownerNavigator.maxTouchPoints || 0);
  return IPADOS_DESKTOP_USER_AGENT_RE.test(userAgent) && maxTouchPoints > 1;
}

function normalizeMobileKhmerTranscriptText(text) {
  const normalizedText = String(text || '');

  if (!normalizedText || !isLikelyIosOrAndroidBrowser()) {
    return normalizedText;
  }

  return normalizedText.replace(
    KHMER_MOBILE_TRANSCRIPT_ARTIFACT_RE,
    KHMER_MOBILE_TRANSCRIPT_ARTIFACT_REPLACEMENT,
  );
}

function getDictionarySnapshotCacheKey(dictionaryConfig) {
  if (!dictionaryConfig) {
    return '';
  }

  return [
    dictionaryConfig.dictionaryName,
    dictionaryConfig.affUrl,
    dictionaryConfig.dicUrl,
  ].join('::');
}

function loadKhmerDictionarySnapshot(dictionaryConfig) {
  const cacheKey = getDictionarySnapshotCacheKey(dictionaryConfig);
  if (!cacheKey) {
    return Promise.resolve(null);
  }

  if (!khmerDictionarySnapshotPromises.has(cacheKey)) {
    khmerDictionarySnapshotPromises.set(
      cacheKey,
      loadDictionary(dictionaryConfig)
        .then((dictionary) => {
          const dictionarySnapshot = createDictionarySnapshot(dictionary);
          if (!dictionarySnapshot) {
            khmerDictionarySnapshotPromises.delete(cacheKey);
          }

          return dictionarySnapshot;
        })
        .catch((error) => {
          khmerDictionarySnapshotPromises.delete(cacheKey);
          throw error;
        }),
    );
  }

  return khmerDictionarySnapshotPromises.get(cacheKey) || Promise.resolve(null);
}

function createKhmerSpellcheckProvider(specification = {}) {
  // Keep Khmer spellcheck behind a worker boundary so the engine can move to WASM later.
  const checkCache = new Map();
  const createWorkerFactory =
    typeof specification.createWorker === 'function'
      ? specification.createWorker
      : null;
  const dictionaryConfig = getDictionaryConfig(specification);
  const suggestDictionaryConfigs =
    getSuggestionDictionaryConfigs(specification);
  const pendingSegmentationSuggestions = new Map();
  const segmentationCache = new Map();
  let prefixSuggestionSnapshotPromise = null;
  const prefixSuggestionCache = new Map();
  const suggestionCache = new Map();
  const validationWorkerRuntime = createWorkerRuntime('validation', {
    dictionaryConfig,
    useDictionarySnapshot: true,
  });
  const auxiliaryWorkerRuntime = createWorkerRuntime('auxiliary', {
    dictionaryConfig,
    suggestDictionaryConfigs,
  });
  const segmentationWorkerRuntime = createWorkerRuntime('segmentation', {
    dictionaryConfig,
  });

  function normalizeCacheKey(word) {
    return normalizeWord(word, 'km');
  }

  function getGlobalPattern(pattern) {
    const flags = pattern.flags.includes('g')
      ? pattern.flags
      : `${pattern.flags}g`;

    return new RegExp(pattern.source, flags);
  }

  function ensureTranscriptWordBoundary(word) {
    return String(word || '')
      .split(KHMER_SEGMENTATION_SEPARATOR)
      .filter(Boolean)
      .map((segment) => `${segment}${KHMER_SEGMENTATION_SEPARATOR}`)
      .join('');
  }

  function shouldCheckWord(word) {
    const normalizedWord = normalizeCacheKey(word);
    return Boolean(normalizedWord && hasAnyWordBaseCharacter(normalizedWord));
  }

  function createWorkerRuntime(channelLabel, options = {}) {
    return {
      channelLabel,
      dictionaryConfig: options.dictionaryConfig || null,
      errorHandler: null,
      initializePromise: null,
      messageHandler: null,
      pendingRequests: new Map(),
      ready: false,
      requestId: 0,
      suggestDictionaryConfigs: Array.isArray(options.suggestDictionaryConfigs)
        ? options.suggestDictionaryConfigs
        : [],
      useDictionarySnapshot: Boolean(options.useDictionarySnapshot),
      worker: null,
    };
  }

  function rejectPendingRequests(workerRuntime, error) {
    workerRuntime.pendingRequests.forEach(({ reject }) => reject(error));
    workerRuntime.pendingRequests.clear();
  }

  function disposeWorker(workerRuntime) {
    if (!workerRuntime?.worker) {
      return;
    }

    workerRuntime.worker.removeEventListener(
      'message',
      workerRuntime.messageHandler,
    );
    workerRuntime.worker.removeEventListener(
      'error',
      workerRuntime.errorHandler,
    );
    workerRuntime.worker.terminate();
    workerRuntime.worker = null;
    workerRuntime.messageHandler = null;
    workerRuntime.errorHandler = null;
    workerRuntime.initializePromise = null;
    workerRuntime.ready = false;
  }

  function handleWorkerMessage(workerRuntime, event) {
    const { id, result, error } = event?.data || {};
    const pendingRequest = workerRuntime.pendingRequests.get(id);
    if (!pendingRequest) {
      return;
    }

    workerRuntime.pendingRequests.delete(id);

    if (error) {
      pendingRequest.reject(new Error(error));
      return;
    }

    pendingRequest.resolve(result);
  }

  function handleWorkerError(workerRuntime, event) {
    const error =
      event?.error instanceof Error
        ? event.error
        : new Error(event?.message || 'Khmer spellcheck worker failed.');

    console.error(
      `Khmer spellcheck worker failed (${workerRuntime.channelLabel}).`,
      error,
    );
    disposeWorker(workerRuntime);
    rejectPendingRequests(workerRuntime, error);
  }

  function ensureWorker(workerRuntime) {
    if (workerRuntime.worker) {
      return workerRuntime.worker;
    }

    const nextWorker =
      createWorkerFactory?.(workerRuntime.channelLabel) ||
      new Worker(new URL('./spellcheck-khmer.worker.ts', import.meta.url), {
        type: 'module',
      });

    if (
      !nextWorker ||
      typeof nextWorker.postMessage !== 'function' ||
      typeof nextWorker.addEventListener !== 'function' ||
      typeof nextWorker.removeEventListener !== 'function' ||
      typeof nextWorker.terminate !== 'function'
    ) {
      throw new TypeError(
        `Khmer spellcheck worker factory must return a Worker-like object for ${workerRuntime.channelLabel}.`,
      );
    }

    workerRuntime.messageHandler = (event) => {
      handleWorkerMessage(workerRuntime, event);
    };
    workerRuntime.errorHandler = (event) => {
      handleWorkerError(workerRuntime, event);
    };

    nextWorker.addEventListener('message', workerRuntime.messageHandler);
    nextWorker.addEventListener('error', workerRuntime.errorHandler);
    workerRuntime.worker = nextWorker;
    return workerRuntime.worker;
  }

  function callWorker(workerRuntime, type, payload = {}) {
    const activeWorker = ensureWorker(workerRuntime);
    const id = `khmer-spellcheck-${workerRuntime.channelLabel}-${workerRuntime.requestId + 1}`;
    workerRuntime.requestId += 1;

    return new Promise((resolve, reject) => {
      workerRuntime.pendingRequests.set(id, { resolve, reject });
      activeWorker.postMessage({ id, payload, type });
    });
  }

  async function initializeWorker(workerRuntime) {
    if (workerRuntime.ready) {
      return true;
    }

    if (!workerRuntime.dictionaryConfig) {
      console.error('Khmer spellcheck dictionary configuration is missing.');
      return false;
    }

    if (!workerRuntime.initializePromise) {
      const initializeStartTime = getKhmerTimingNow();
      let snapshotLoadMs = 0;
      let dispatchMs = 0;

      workerRuntime.initializePromise = Promise.resolve()
        .then(async () => {
          if (!workerRuntime.useDictionarySnapshot) {
            return null;
          }

          const snapshotStartTime = getKhmerTimingNow();
          const dictionaryData = await loadKhmerDictionarySnapshot(
            workerRuntime.dictionaryConfig,
          );
          snapshotLoadMs = getKhmerTimingNow() - snapshotStartTime;

          if (!dictionaryData) {
            console.error(
              'Khmer spellcheck dictionary snapshot could not be prepared.',
            );
            return null;
          }

          return dictionaryData;
        })
        .then((dictionaryData) => {
          if (workerRuntime.useDictionarySnapshot && !dictionaryData) {
            return { ready: false };
          }

          const dispatchStartTime = getKhmerTimingNow();
          const initializePayload = {
            dictionaryConfig: workerRuntime.dictionaryConfig,
          };

          if (dictionaryData) {
            initializePayload.dictionaryData = dictionaryData;
          }

          if (workerRuntime.suggestDictionaryConfigs.length) {
            initializePayload.suggestDictionaryConfigs =
              workerRuntime.suggestDictionaryConfigs;
          }

          const initializeRequest = callWorker(
            workerRuntime,
            'initialize',
            initializePayload,
          );
          dispatchMs = getKhmerTimingNow() - dispatchStartTime;
          return initializeRequest;
        })
        .then((result) => {
          workerRuntime.ready = Boolean(result?.ready);
          if (!workerRuntime.ready) {
            workerRuntime.initializePromise = null;
          }

          logKhmerProviderTiming(
            'initialize',
            initializeStartTime,
            `channel=${workerRuntime.channelLabel} ready=${String(workerRuntime.ready)} payload=${workerRuntime.useDictionarySnapshot ? 'snapshot' : 'config'} snapshotLoad=${snapshotLoadMs.toFixed(1)}ms dispatch=${dispatchMs.toFixed(1)}ms`,
          );

          return workerRuntime.ready;
        })
        .catch((error) => {
          console.error(
            `Failed to initialize Khmer spellcheck worker (${workerRuntime.channelLabel}).`,
            error,
          );
          logKhmerProviderTiming(
            'initialize',
            initializeStartTime,
            `channel=${workerRuntime.channelLabel} ready=false payload=${workerRuntime.useDictionarySnapshot ? 'snapshot' : 'config'} snapshotLoad=${snapshotLoadMs.toFixed(1)}ms dispatch=${dispatchMs.toFixed(1)}ms`,
          );
          workerRuntime.initializePromise = null;
          workerRuntime.ready = false;
          return false;
        });
    }

    return workerRuntime.initializePromise;
  }

  function initialize() {
    return initializeWorker(validationWorkerRuntime);
  }

  function initializeAuxiliaryWorker() {
    return initializeWorker(auxiliaryWorkerRuntime);
  }

  function initializeSegmentationWorker() {
    return initializeWorker(segmentationWorkerRuntime);
  }

  async function loadPrefixSuggestionSnapshots() {
    if (prefixSuggestionSnapshotPromise) {
      return prefixSuggestionSnapshotPromise;
    }

    const prefixConfigs = (
      suggestDictionaryConfigs.length
        ? suggestDictionaryConfigs
        : [dictionaryConfig]
    ).filter(Boolean);

    prefixSuggestionSnapshotPromise = Promise.allSettled(
      prefixConfigs.map((config) => loadKhmerDictionarySnapshot(config)),
    ).then((results) =>
      results
        .filter(
          (result) => result.status === 'fulfilled' && result.value?.loaded,
        )
        .map((result) => result.value),
    );

    return prefixSuggestionSnapshotPromise;
  }

  async function checkWords(words) {
    const checkWordsStartTime = getKhmerTimingNow();
    const results = new Map();
    const uniqueWords = Array.from(new Set(words));
    const missingWords = new Set();
    const normalizedWordsByWord = new Map();
    let skippedWordCount = 0;

    if (!uniqueWords.length) {
      logKhmerProviderTiming('checkWords', checkWordsStartTime, 'words=0');
      return results;
    }

    uniqueWords.forEach((word) => {
      const normalizedWord = normalizeCacheKey(word);
      normalizedWordsByWord.set(word, normalizedWord);

      if (!normalizedWord || !hasAnyWordBaseCharacter(normalizedWord)) {
        results.set(word, true);
        skippedWordCount += 1;
        return;
      }

      if (checkCache.has(normalizedWord)) {
        results.set(word, checkCache.get(normalizedWord) ?? true);
        return;
      }

      missingWords.add(normalizedWord);
    });

    const cacheHitCount =
      uniqueWords.length - skippedWordCount - missingWords.size;

    if (!missingWords.size) {
      logKhmerProviderTiming(
        'checkWords',
        checkWordsStartTime,
        `words=${uniqueWords.length} lookup=0 cacheHits=${cacheHitCount} skipped=${skippedWordCount}`,
      );
      return results;
    }

    const readyState = await initialize();
    if (!readyState) {
      uniqueWords.forEach((word) => {
        if (!results.has(word)) {
          results.set(word, true);
        }
      });

      logKhmerProviderTiming(
        'checkWords',
        checkWordsStartTime,
        `words=${uniqueWords.length} lookup=${missingWords.size} cacheHits=${cacheHitCount} skipped=${skippedWordCount} ready=false`,
      );

      return results;
    }

    const workerResults = await callWorker(
      validationWorkerRuntime,
      'checkWords',
      {
        words: Array.from(missingWords),
      },
    );

    Object.entries(workerResults || {}).forEach(([word, isCorrect]) => {
      checkCache.set(word, Boolean(isCorrect));
    });

    uniqueWords.forEach((word) => {
      if (results.has(word)) {
        return;
      }

      const normalizedWord = normalizedWordsByWord.get(word);
      results.set(word, checkCache.get(normalizedWord) ?? true);
    });

    logKhmerProviderTiming(
      'checkWords',
      checkWordsStartTime,
      `words=${uniqueWords.length} lookup=${missingWords.size} cacheHits=${cacheHitCount} skipped=${skippedWordCount}`,
    );

    return results;
  }

  async function getSuggestions(word) {
    const normalizedWord = normalizeCacheKey(word);
    const suggestionStartTime = getKhmerTimingNow();
    const wordLength = Array.from(normalizedWord || '').length;

    if (!normalizedWord || !hasAnyWordBaseCharacter(normalizedWord)) {
      return [];
    }

    if (suggestionCache.has(normalizedWord)) {
      const cachedSuggestions = suggestionCache.get(normalizedWord) || [];

      logKhmerProviderTiming(
        'suggest',
        suggestionStartTime,
        `channel=${auxiliaryWorkerRuntime.channelLabel} cache=hit suggestions=${cachedSuggestions.length} chars=${wordLength}`,
      );

      return cachedSuggestions;
    }

    const readyState = await initializeAuxiliaryWorker();
    if (!readyState) {
      logKhmerProviderTiming(
        'suggest',
        suggestionStartTime,
        `channel=${auxiliaryWorkerRuntime.channelLabel} cache=miss suggestions=0 chars=${wordLength} ready=false`,
      );
      return [];
    }

    const suggestions = await callWorker(auxiliaryWorkerRuntime, 'suggest', {
      limit: 3,
      word: normalizedWord,
    });
    const normalizedSuggestions = Array.isArray(suggestions) ? suggestions : [];
    suggestionCache.set(normalizedWord, normalizedSuggestions);

    logKhmerProviderTiming(
      'suggest',
      suggestionStartTime,
      `channel=${auxiliaryWorkerRuntime.channelLabel} cache=miss suggestions=${normalizedSuggestions.length} chars=${wordLength}`,
    );

    return normalizedSuggestions;
  }

  async function getPrefixSuggestions(word, limit = 8) {
    const normalizedWord = normalizeCacheKey(word);
    const maxSuggestions = Math.max(1, Number(limit) || 8);

    if (!normalizedWord || !hasAnyWordBaseCharacter(normalizedWord)) {
      return [];
    }

    const cacheKey = `${normalizedWord}::${maxSuggestions}`;
    if (prefixSuggestionCache.has(cacheKey)) {
      return prefixSuggestionCache.get(cacheKey) || [];
    }

    const snapshots = await loadPrefixSuggestionSnapshots();
    const suggestions = getDictionaryPrefixSuggestions(
      snapshots,
      normalizedWord,
      maxSuggestions,
    );

    prefixSuggestionCache.set(cacheKey, suggestions);
    return suggestions;
  }

  async function getSegmentationSuggestion(word) {
    const normalizedWord = normalizeCacheKey(word);
    const segmentationStartTime = getKhmerTimingNow();
    const wordLength = Array.from(normalizedWord || '').length;

    if (!normalizedWord || !hasAnyWordBaseCharacter(normalizedWord)) {
      return '';
    }

    if (segmentationCache.has(normalizedWord)) {
      const cachedSuggestion = segmentationCache.get(normalizedWord) || '';

      logKhmerProviderTiming(
        'segment',
        segmentationStartTime,
        `channel=${segmentationWorkerRuntime.channelLabel} cache=hit found=${String(Boolean(cachedSuggestion))} chars=${wordLength}`,
      );

      return cachedSuggestion;
    }

    if (pendingSegmentationSuggestions.has(normalizedWord)) {
      const pendingSuggestion =
        pendingSegmentationSuggestions.get(normalizedWord);

      logKhmerProviderTiming(
        'segment',
        segmentationStartTime,
        `channel=${segmentationWorkerRuntime.channelLabel} cache=pending chars=${wordLength}`,
      );

      return pendingSuggestion;
    }

    const pendingSuggestion = (async () => {
      const readyState = await initializeSegmentationWorker();
      if (!readyState) {
        logKhmerProviderTiming(
          'segment',
          segmentationStartTime,
          `channel=${segmentationWorkerRuntime.channelLabel} cache=miss found=false chars=${wordLength} ready=false`,
        );
        return '';
      }

      const segmentationSuggestion = await callWorker(
        segmentationWorkerRuntime,
        'segment',
        {
          word: normalizedWord,
        },
      );
      const normalizedSuggestion =
        typeof segmentationSuggestion === 'string'
          ? segmentationSuggestion
          : '';
      segmentationCache.set(normalizedWord, normalizedSuggestion);

      logKhmerProviderTiming(
        'segment',
        segmentationStartTime,
        `channel=${segmentationWorkerRuntime.channelLabel} cache=miss found=${String(Boolean(normalizedSuggestion))} chars=${wordLength}`,
      );

      return normalizedSuggestion;
    })();

    pendingSegmentationSuggestions.set(normalizedWord, pendingSuggestion);

    try {
      return await pendingSuggestion;
    } finally {
      pendingSegmentationSuggestions.delete(normalizedWord);
    }
  }

  async function postProcessTranscriptText(text, options = {}) {
    const normalizedText = normalizeMobileKhmerTranscriptText(text);
    const wordPattern =
      options?.specification?.wordPattern instanceof RegExp
        ? options.specification.wordPattern
        : specification.wordPattern instanceof RegExp
          ? specification.wordPattern
          : null;

    if (!normalizedText || !(wordPattern instanceof RegExp)) {
      return normalizedText;
    }

    const matches = Array.from(
      normalizedText.matchAll(getGlobalPattern(wordPattern)),
    );

    if (!matches.length) {
      return normalizedText;
    }

    const uniqueWords = Array.from(
      new Set(matches.map((match) => match?.[0] ?? '').filter(Boolean)),
    );
    const spellcheckResults = await checkWords(uniqueWords);
    const replacements = new Map();

    await Promise.all(
      uniqueWords.map(async (word) => {
        let nextWord = word;

        if (!(spellcheckResults.get(word) ?? true)) {
          const segmentationSuggestion = await getSegmentationSuggestion(word);

          if (segmentationSuggestion) {
            nextWord = segmentationSuggestion;
          }
        }

        replacements.set(word, ensureTranscriptWordBoundary(nextWord) || word);
      }),
    );

    let nextText = '';
    let lastIndex = 0;

    matches.forEach((match) => {
      const word = match?.[0] ?? '';
      const startIndex = Number(match?.index);

      if (!word || !Number.isInteger(startIndex) || startIndex < lastIndex) {
        return;
      }

      const replacement = replacements.get(word) || word;
      let nextLastIndex = startIndex + word.length;

      nextText += normalizedText.slice(lastIndex, startIndex);
      nextText += replacement;

      if (
        replacement.endsWith(KHMER_SEGMENTATION_SEPARATOR) &&
        normalizedText.charAt(nextLastIndex) === KHMER_SEGMENTATION_SEPARATOR
      ) {
        nextLastIndex += 1;
      }

      lastIndex = nextLastIndex;
    });

    nextText += normalizedText.slice(lastIndex);
    return nextText;
  }

  function dispose() {
    const disposedError = new Error('Khmer spellcheck provider disposed.');

    rejectPendingRequests(validationWorkerRuntime, disposedError);
    rejectPendingRequests(auxiliaryWorkerRuntime, disposedError);
    rejectPendingRequests(segmentationWorkerRuntime, disposedError);
    disposeWorker(validationWorkerRuntime);
    disposeWorker(auxiliaryWorkerRuntime);
    disposeWorker(segmentationWorkerRuntime);
    pendingSegmentationSuggestions.clear();
    checkCache.clear();
    prefixSuggestionCache.clear();
    prefixSuggestionSnapshotPromise = null;
    segmentationCache.clear();
    suggestionCache.clear();
  }

  return {
    languageCode: 'km',
    checkWords,
    dispose,
    getPrefixSuggestions,
    getSegmentationSuggestion,
    getSuggestions,
    initialize,
    isReady: () => validationWorkerRuntime.ready,
    postProcessTranscriptText,
    shouldCheckWord,
  };
}

export { createKhmerSpellcheckProvider };
